and type = #{type,jdbcType=INTEGER}

/*保险的暂时先隐藏这5个类型*/
    AND id NOT IN (17,14,16,23,24)

mapper.select:
select
s.*
from survey_task_info s
left join survey_case_direction t on s.id = t.task_id and t.survey_info_id = #{surveyInfoId,jdbcType=BIGINT} and t.direction_name = #{directionName,jdbcType=VARCHAR}
where t.id is not null

    and t.id != #{directionId,jdbcType=BIGINT}

SELECT a.id,a.name as taskClassification,COUNT(aa.task_id) as taskNumber FROM survey_task_info a LEFT JOIN ( SELECT b.task_id FROM survey_case_direction b LEFT JOIN survey_risk_case_info c ON c.id = b.survey_info_id LEFT JOIN survey_consignor d ON c.entrust_org_id=d.id LEFT JOIN survey_assign_org e ON e.survey_info_id=c.id WHERE b.delete_flag=0 AND c.delete_flag=0 AND d.delete_flag=0 AND d.org_attr=2 AND e.delete_flag=0 and d.org_state = 0
and
(b.area_type=#{item.areaType} and b.region_type=#{item.regionType})
AND c.entrust_org_id IN(${platform})
and e.review_time is not null and e.review_time >= #{startTime} and e.review_time <= #{endTime}
and c.entrust_report_end_date is not null and c.entrust_report_end_date >= #{startTime} and c.entrust_report_end_date <= #{endTime}
)aa ON a.id=aa.task_id WHERE a.type=2 AND a.delete_flag=0 GROUP BY a.id,a.name
